package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock is the production Clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It is safe for use by multiple goroutines.
type Limiter struct {
	mu       sync.Mutex
	rate     float64       // tokens per second
	burst    float64       // bucket capacity
	tokens   float64       // current tokens
	last     time.Time     // last refill time
	clock    Clock
}

// ErrInvalidConfig is returned by New for non-positive rate or burst.
var ErrInvalidConfig = errors.New("ratelimit: rate and burst must be > 0")

// New creates a Limiter that refills rate tokens per second, with a
// maximum capacity of burst tokens. The bucket starts full.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is like New but accepts an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 || burst <= 0 {
		return nil, ErrInvalidConfig
	}
	b := float64(burst)
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  b,
		tokens: b,
		last:   now,
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time clock.Now().
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
func (l *Limiter) AllowN(n int) bool {
	return l.AllowNAt(l.clock.Now(), n)
}

// AllowNAt reports whether n tokens may be consumed at the given time.
// It is primarily useful for testing; AllowN delegates here.
func (l *Limiter) AllowNAt(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// RetryAfter returns the duration until n tokens would be available,
// or 0 if n tokens are available now. n must be non-negative.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.advance(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
