// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created by New; the zero value is not usable.
type Limiter struct {
	mu       sync.Mutex
	capacity int
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

var (
	ErrNonPositiveCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given burst capacity (tokens), refill
// rate (tokens per second), and clock. If clock is nil, the real clock
// is used.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		tokens:   float64(capacity),
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// MustNew is like New but panics on invalid arguments.
func MustNew(capacity int, rate float64, clock Clock) *Limiter {
	l, err := New(capacity, rate, clock)
	if err != nil {
		panic(fmt.Sprintf("ratelimit: %v", err))
	}
	return l
}

// advance refills tokens based on elapsed time. Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if elapsed := now.Sub(l.last); elapsed > 0 {
		l.tokens += elapsed.Seconds() * l.rate
		if l.tokens > float64(l.capacity) {
			l.tokens = float64(l.capacity)
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now,
// consuming them if so.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns the duration after which a request for n tokens
// would succeed, computed at time now. It returns 0 if the request
// would succeed immediately.
func (l *Limiter) RetryAfter(now time.Time, n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	if float64(n) <= l.tokens {
		return 0
	}
	need := float64(n) - l.tokens
	return time.Duration(need / l.rate * float64(time.Second))
}
