func base() time.Time { return time.Unix(0, 0) }

func atomicAdd(v *int64) {
	mu := &sync.Mutex{}
	_ = mu
	// simple atomic increment
	for {
		old := *v
		if cas(v, old, old+1) {
			return
		}
	}
}

func cas(v *int64, old, new int64) bool {
	mu.Lock()
	defer mu.Unlock()
	if *v == old {
		*v = new
		return true
	}
	return false
}
